server_scripts.script:
from one_bpmn.one_bpmn.integrations.google_drive import (
	GoogleDriveConfigError,
	download_file_text,
)

source_guideline = task_data.get("source_guideline")

if not source_guideline:
	frappe.log_error(
		title="Drive Script: fetch_guideline_content — missing source_guideline",
		message=f"task_data keys: {list(task_data.keys())}",
	)
else:
	try:
		entry = frappe.get_doc("Document Register", source_guideline)
		result["guideline_content"] = download_file_text(entry.drive_file_id)
	except GoogleDriveConfigError as e:
		frappe.log_error(title="Drive Script: fetch_guideline_content config error", message=str(e))
	except Exception:
		frappe.log_error(title="Drive Script: fetch_guideline_content failed", message=frappe.get_traceback())

import re as _re

from one_bpmn.one_bpmn.integrations.google_drive import (
	GoogleDriveConfigError,
	download_file_text,
	list_files,
)

folder_ids_raw = task_data.get("drive_folder_ids") or ""
folder_ids = [f.strip() for f in folder_ids_raw.split(",") if f.strip()]
requirement_var = "requirement_text"
output_var = "reference_context"

requirement_text = task_data.get(requirement_var) or ""
stopwords = {
	"the", "a", "an", "for", "and", "or", "of", "to", "in", "on", "with",
	"is", "are", "be", "as", "that", "this", "we", "need", "procedure", "document",
}
keywords = [
	w for w in _re.findall(r"[a-zA-Z]{4,}", requirement_text.lower())
	if w not in stopwords
]

if not folder_ids:
	result[output_var] = ""
else:
	candidates = []
	try:
		for folder_id in folder_ids:
			for f in list_files(folder_id):
				try:
					text = download_file_text(f["id"], f.get("mimeType", ""))
				except Exception:
					continue
				haystack = (f["name"] + "\n" + text).lower()
				score = sum(haystack.count(kw) for kw in keywords)
				if score > 0:
					candidates.append((score, f["name"], text))
	except GoogleDriveConfigError as e:
		frappe.log_error(title="Drive Script: gather_reference config error", message=str(e))
		candidates = []
	except Exception:
		frappe.log_error(title="Drive Script: gather_reference failed", message=frappe.get_traceback())
		candidates = []

	candidates.sort(key=lambda c: c[0], reverse=True)
	top = candidates[:2]
	if top:
		blocks = []
		for _score, fname, text in top:
			snippet = text.strip()
			if len(snippet) > 2000:
				snippet = snippet[:2000] + "\n...[truncated]"
			blocks.append(f"## {fname}\n\n{snippet}")
		result[output_var] = "\n\n".join(blocks)
	else:
		result[output_var] = ""
